WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_grass_g_uniform'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '草每天匀速生长', 'kp-grass-g-uniform', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "草匀速生长原理"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果不派 X 头牛专门去吃新长出的草，草场永远吃不完！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "既然草每天长 X 份，那么就必须分配 X 头牛每天专门负责吃新长出来的草。剩下的牛（N - X 头）才是真正负责消耗原有库存 Y 的牛。"}]}]}$$ AS jsonb), NULL, '草每天匀速生长的核心考点与实战推导。', category_node.id, CAST('["数量关系", "牛吃草问题", "草每天匀速生长"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_grass_g_uniform", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
